mapper.update:
UPDATE guacamole_user_password_reset
SET used = #{now,jdbcType=TIMESTAMP}
WHERE token_hash = #{tokenHash,jdbcType=BINARY}
    AND used IS NULL
    AND expires > #{now,jdbcType=TIMESTAMP}

UPDATE guacamole_user_password_reset
SET used = #{now,jdbcType=TIMESTAMP}
WHERE user_id = #{userID,jdbcType=INTEGER}
    AND used IS NULL

mapper.select:
SELECT COUNT(*)
FROM guacamole_user_password_reset
WHERE user_id = #{userID,jdbcType=INTEGER}
    AND created > #{since,jdbcType=TIMESTAMP}
